import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import test from 'node:test';
function setup(){const c=vm.createContext({});c.window=c;for(const f of ['model.js','menu-renderer.js','menu-layouts.js','reference-design.js'])vm.runInContext(readFileSync(new URL(f,import.meta.url),'utf8'),c);return c;}
test('uploaded reference analysis is explicitly simulated and requires confirmation',()=>{const c=setup(),s=c.MenuModel.create(),ref=c.MenuReference;Object.assign(ref.ensure(s),{source:'upload',name:'test.png',image:'data:image/png;base64,abc'});ref.beginAnalysis(s);assert.equal(s.reference.analysis.status,'running');assert.equal(ref.ready(s),false);ref.finishAnalysis(s);assert.equal(s.reference.analysis.status,'ready');assert.equal(s.reference.recipe,'collage');assert.equal(s.reference.interpreted,false);assert.match(ref.view(s),/预编写示例/);assert.match(ref.view(s),/修正分析结果/);assert.doesNotMatch(ref.view(s),/请指定参考图的构图特征/);});
test('replacing a reference clears analysis and invalidates confirmation',()=>{const c=setup(),s=c.MenuModel.create(),ref=c.MenuReference;ref.choose(s,'hero');ref.beginAnalysis(s);ref.finishAnalysis(s);s.reference.analysis.status='ready';s.reference.interpreted=true;s.reference.samples=true;ref.confirm(s,0);ref.choose(s,'text');assert.equal(s.reference.analysis.status,'idle');assert.equal(ref.ready(s),false);ref.beginAnalysis(s);ref.finishAnalysis(s);assert.equal(s.reference.recipe,'text');assert.equal(s.reference.analysis.kind,'gallery');});
test('reference defaults adapt and requires sample confirmation',()=>{const c=setup(),s=c.MenuModel.create(),r=c.MenuReference;r.ensure(s);assert.equal(s.reference.mode,'adapt');assert.equal(r.ready(s),false);r.choose(s,'hero');assert.equal(s.reference.source,'gallery');s.reference.analysis.status='ready';s.reference.interpreted=true;s.reference.samples=true;r.confirm(s,0);assert.equal(r.ready(s),true);r.invalidate(s);assert.equal(r.ready(s),false)});
test('layouts differ and all supported compositions fit without content overlaps',()=>{const c=setup(),s=c.MenuModel.create();let layouts=[];for(const [w,h] of [[1920,1080],[1080,1920],[210,297]])for(const density of [2,4,6])for(const layout of ['hero','collage','editorial','text','grid']){Object.assign(s,{width:w,height:h,density,layout});for(const p of c.MenuModel.pages(s)){const a=c.MenuLayouts.positions(s,p),H=1000*h/w;for(const x of a){assert.ok(x.x>=32&&x.y>=145);assert.ok(x.x+x.cw<=968.01&&x.y+x.ch<=H-51)}for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const x=a[i],y=a[j];assert.ok(!(x.x<y.x+y.cw&&x.x+x.cw>y.x&&x.y<y.y+y.ch&&x.y+x.ch>y.y),`${layout} overlap`)}if(w===1920&&density===4&&p.id==='p0')layouts.push(JSON.stringify(a.map(({x,y,cw,ch})=>[x,y,cw,ch])));}}assert.equal(new Set(layouts).size,5)});
test('reference change retains old samples but invalidates downstream',()=>{const c=setup(),s=c.MenuModel.create(),r=c.MenuReference;r.ensure(s);r.choose(s,'hero');s.reference.samples=true;s.reference.analysis.status='ready';s.reference.interpreted=true;r.confirm(s,0);r.choose(s,'collage');assert.equal(r.ready(s),false);assert.ok(s.reference.previous);assert.equal(s.reference.recipe,'collage')});
test('locked component coordinates and size remain fixed',()=>{const c=setup(),s=c.MenuModel.create();s.layout='hero';const p=c.MenuModel.pages(s)[0],z=c.MenuLayouts.positions(s,p)[0];s.overrides[z.item.id]={...z,item:undefined,locked:true};s.variant=1;const next=c.MenuLayouts.positions(s,p)[0];assert.equal(next.x,z.x);assert.equal(next.cw,z.cw)});
test('all preview clip IDs are unique and prices remain exact',()=>{const c=setup(),s=c.MenuModel.create();s.layout='collage';s.items[0].price=48.55;const p=c.MenuModel.pages(s)[0],svg=c.MenuRenderer.svg(s,p)+c.MenuRenderer.svg(s,p);const ids=[...svg.matchAll(/id="([^"]+)"/g)].map(x=>x[1]);assert.equal(ids.length,new Set(ids).size);assert.ok(svg.includes('¥ 48.55'));});
test('style-only and layout-only honor their scope',()=>{const c=setup(),s=c.MenuModel.create(),r=c.MenuReference;r.choose(s,'collage');s.reference.mode='style';assert.equal(r.sample(s,0).layout,'grid');s.reference.mode='adapt';s.reference.focus='layout';s.style='ink';assert.equal(r.sample(s,0).style,'ink');assert.equal(r.sample(s,0).layout,'collage')});
test('shared SVG renderer uses brand colors for preview and export',()=>{const c=setup(),s=c.MenuModel.create();s.layout='collage';Object.assign(c.MenuModel.ensureBrand(s),{primary:'#123456',secondary:'#f0e0d0',accent:'#654321',policy:'strict'});const svg=c.MenuRenderer.svg(s,c.MenuModel.pages(s)[0]);assert.match(svg,/#123456/);assert.match(svg,/#f0e0d0/);assert.match(svg,/#654321/);s.brandMaterials.policy='reference';assert.doesNotMatch(c.MenuRenderer.svg(s,c.MenuModel.pages(s)[0]),/#123456/);});
